#include "techpulse/publish/report.hpp"
#include <fstream>
#include <iomanip>
#include <sstream>
namespace techpulse::publish { bool write_daily_report(const std::filesystem::path& root,const std::string& date,const std::vector<model::ScoredItem>& items,const std::vector<std::string>& errors){std::filesystem::create_directories(root/"reports/daily");std::ofstream out(root/"reports/daily"/(date+".md"));if(!out)return false;out<<"# DevSignal Radar · "<<date<<"\n\n"<<"候选信号："<<items.size()<<"；失败来源："<<errors.size()<<"\n\n## Top Signals\n\n";for(const auto&i:items){if(i.excluded)continue;out<<"### ["<<std::fixed<<std::setprecision(1)<<i.score.total<<"] "<<i.item.title<<"\n\n来源："<<i.item.source_type<<"  \\n[原文链接]("<<i.item.url<<")\n\n";for(const auto&r:i.reasons)out<<"- "<<r<<"\n";out<<"\n";}std::filesystem::create_directories(root/"site/public/data");std::ofstream json(root/"site/public/data/latest.json");json<<"{\"date\":\""<<date<<"\",\"items\":[";bool first=true;for(const auto&i:items){if(i.excluded)continue;if(!first)json<<",";first=false;json<<"{\"title\":\""<<i.item.title<<"\",\"url\":\""<<i.item.url<<"\",\"source\":\""<<i.item.source_type<<"\",\"score\":"<<i.score.total<<"}";}json<<"]}";return true;} }
